const canvas=document.querySelector('#crystal'),ctx=canvas.getContext('2d');
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let reduced=motionQuery.matches;
let w=0,h=0,dpr=1,mouse={x:0,y:0},frame=0,visible=true;
const phi=(1+Math.sqrt(5))/2;
const vertices=[[-1,phi,0],[1,phi,0],[-1,-phi,0],[1,-phi,0],[0,-1,phi],[0,1,phi],[0,-1,-phi],[0,1,-phi],[phi,0,-1],[phi,0,1],[-phi,0,-1],[-phi,0,1]];
const faces=[[0,11,5],[0,5,1],[0,1,7],[0,7,10],[0,10,11],[1,5,9],[5,11,4],[11,10,2],[10,7,6],[7,1,8],[3,9,4],[3,4,2],[3,2,6],[3,6,8],[3,8,9],[4,9,5],[2,4,11],[6,2,10],[8,6,7],[9,8,1]];
function resize(){w=canvas.clientWidth;h=canvas.clientHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;if(reduced)draw(0)}
function path(points){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath()}
function headline(x,y,offset=0){ctx.fillStyle='#e8e3db';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`400 ${Math.min(w*.165,245)}px Georgia,serif`;ctx.fillText('Bismus',x+offset,y)}
function draw(time){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const mobile=w<700,cx=w/2,cy=h*(mobile?.405:.43),radius=Math.min(w*(mobile?.22:.105),h*.17);const t=reduced?.6:time*.00013;const ax=.28+Math.sin(t*.7)*.15+mouse.y*.12,ay=t+mouse.x*.16,az=.12;const cos=Math.cos,sin=Math.sin;
 const points=vertices.map(([x,y,z])=>{let a=x*cos(ay)+z*sin(ay),b=-x*sin(ay)+z*cos(ay);let c=y*cos(ax)-b*sin(ax),d=y*sin(ax)+b*cos(ax);let e=a*cos(az)-c*sin(az),f=a*sin(az)+c*cos(az);const s=4.8/(4.8-d);return{x:cx+e*radius*s,y:cy+f*radius*s,z:d}});
 const glow=ctx.createRadialGradient(cx,cy,0,cx,cy,radius*3);glow.addColorStop(0,'#b9a0d00e');glow.addColorStop(1,'#b9a0d000');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);headline(cx,cy+6);
 const sorted=faces.map(f=>({p:f.map(i=>points[i]),z:f.reduce((a,i)=>a+points[i].z,0)/3})).sort((a,b)=>a.z-b.z);
 sorted.forEach(({p,z},i)=>{ctx.save();path(p);ctx.clip();let gradient=ctx.createLinearGradient(p[0].x,p[0].y,p[1].x,p[2].y);gradient.addColorStop(0,`rgba(${i%3===0?'202,178,225':'144,174,184'},${.10+(z+2)*.035})`);gradient.addColorStop(.48,'rgba(12,16,23,.54)');gradient.addColorStop(1,'rgba(223,213,230,.19)');ctx.fillStyle=gradient;ctx.fillRect(cx-radius*3,cy-radius*3,radius*6,radius*6);if(z>0){ctx.globalAlpha=.3;ctx.translate((i%3-1)*radius*.12,(i%2?1:-1)*radius*.08);headline(cx,cy+6,(i%2?1:-1)*radius*.09);ctx.globalAlpha=1}ctx.restore();path(p);ctx.lineWidth=z>.4?.85:.45;ctx.strokeStyle=z>.4?'rgba(218,213,234,.44)':'rgba(175,174,206,.17)';ctx.stroke();if(z>.6){ctx.save();ctx.translate(1.3,-.5);path(p);ctx.strokeStyle='rgba(188,133,215,.24)';ctx.stroke();ctx.restore()}});
 ctx.fillStyle='#a6a2ae';ctx.font=`400 ${mobile?8:10}px monospace`;ctx.textAlign='center';ctx.letterSpacing='5px';ctx.fillText('S Y S T E M',cx,cy+Math.min(w*.105,155));ctx.letterSpacing='0px';if(!reduced&&visible)frame=requestAnimationFrame(draw)}
window.addEventListener('resize',resize);window.addEventListener('pointermove',e=>{mouse.x=e.clientX/innerWidth-.5;mouse.y=e.clientY/innerHeight-.5},{passive:true});motionQuery.addEventListener('change',e=>{reduced=e.matches;cancelAnimationFrame(frame);draw(0)});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;cancelAnimationFrame(frame);if(visible)draw(performance.now())}).observe(canvas);resize();
const details={launcher:['Launcher — Der Einstieg','Die Launcher-Perspektive stellt den Zugang zur Spielwelt in den Mittelpunkt: übersichtlich, bewusst und als eigenständiger Teil des Systems. Diese Landingpage zeigt die Designrichtung; ein Produktdownload ist hier noch nicht hinterlegt.'],engine:['Engine — Das Fundament','Die Engine-Perspektive richtet den Blick auf das technische Fundament und das Zusammenspiel der Systemteile. Die hier gezeigte Darstellung ist eine konzeptionelle Einführung und keine Aussage über verfügbare Runtime-Funktionen.'],graphics:['Graphics — Der Ausdruck','Die Graphics-Perspektive erkundet die Wirkung von Licht, Materialien und Atmosphäre. Der Kristall dieser Seite interpretiert diesen Gedanken als visuelles Motiv. Er ist eine eigenständige Canvas-Animation und keine Vorschau auf die Spielgrafik.']};
document.querySelectorAll('[data-module]').forEach(button=>button.addEventListener('click',()=>{const region=document.querySelector('#module-detail'),wasOpen=button.getAttribute('aria-expanded')==='true';document.querySelectorAll('[data-module]').forEach(b=>{b.setAttribute('aria-expanded','false');b.querySelector('span').textContent='+'});region.hidden=wasOpen;if(!wasOpen){const [title,copy]=details[button.dataset.module];region.replaceChildren();const heading=document.createElement('h3'),p=document.createElement('p');heading.textContent=title;p.textContent=copy;region.append(heading,p);button.setAttribute('aria-expanded','true');button.querySelector('span').textContent='−';region.scrollIntoView({behavior:reduced?'instant':'smooth',block:'nearest'})}}));
